import 'dart:convert';import 'package:flutter/material.dart';import 'package:flutter/services.dart';import 'package:intl/intl.dart';import '../../../core/data/astro_repository.dart';import '../../../core/data/local_database.dart';import '../../../core/models/reading.dart';import '../../../core/models/zodiac_sign.dart';import '../../../core/theme/app_theme.dart';import '../../../core/services/astro_clock.dart';import '../../../features/journal/presentation/journal_screen.dart';import '../../../features/share/presentation/share_card_screen.dart';import '../../../features/readings/presentation/period_readings_screen.dart';import '../../../shared/widgets/app_components.dart';
class TodayScreen extends StatefulWidget{const TodayScreen({super.key});@override State<TodayScreen> createState()=>_TodayScreenState();}
class _TodayScreenState extends State<TodayScreen>{String sign='aries',category='general';List<HoroscopeReading> readings=[];List<String> enabledCategories=['general','love','career','wellbeing'];bool loading=true;DateTime selectedDate=DateTime(2026,11,18);
@override void initState(){super.initState();_load();}
Future<void> _load()async{sign=await AstroRepository.instance.selectedSign();enabledCategories=await AstroRepository.instance.enabledCategories();if(!enabledCategories.contains(category))category=enabledCategories.first;selectedDate=AstroClock.editorialToday();try{final raw=await rootBundle.loadString('assets/content/daily-2026-11-18.json');final doc=jsonDecode(raw) as Map<String,dynamic>;readings=(doc['readings'] as List).map((e)=>HoroscopeReading.fromJson({...Map<String,dynamic>.from(e),'date':doc['date']})).toList();}catch(_){}final db=await LocalDatabase.instance.database;final cache=await db.query('content_cache');for(final item in cache){try{final doc=jsonDecode(item['payload'] as String);if(doc is Map&&doc['pack_type']=='daily_horoscopes'&&doc['readings'] is List){final parsed=(doc['readings'] as List).map((e)=>HoroscopeReading.fromJson({...Map<String,dynamic>.from(e),'date':doc['date']})).toList();readings=[...readings,...parsed];}}catch(_){}}if(mounted){setState(()=>loading=false);final r=reading;if(r!=null)await AstroRepository.instance.recordRead(r.id);}}
HoroscopeReading? get reading{final rows=readings.where((r)=>r.signId==sign&&r.category==category&&r.status=='published'&&r.periodStart==DateFormat('yyyy-MM-dd').format(selectedDate)).toList();return rows.isEmpty?null:rows.first;}
@override Widget build(BuildContext context){final s=zodiacById[sign]!;return ListView(padding:const EdgeInsets.all(20),children:[Row(children:[const Expanded(child:Text('A S T R O D A I L Y',style:TextStyle(color:AppTheme.muted,fontWeight:FontWeight.w800,letterSpacing:2,fontSize:10))),Text(DateFormat('EEEE, MMM d').format(selectedDate),style:const TextStyle(color:AppTheme.muted,fontSize:12))]),const SizedBox(height:23),Text('A little cosmic\nclarity for today.',style:Theme.of(context).textTheme.headlineLarge),const SizedBox(height:8),const Text('A moment to pause, reflect and explore.'),const SizedBox(height:20),Card(child:ListTile(leading:Text(s.glyph,style:const TextStyle(fontSize:31,color:AppTheme.primary)),title:Text(s.name,style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text(s.dates),trailing:const Text('CHANGE',style:TextStyle(color:AppTheme.primary,fontSize:10,fontWeight:FontWeight.w800)),onTap:_chooseSign)),const SizedBox(height:19),Row(children:[Expanded(child:Text('Your daily reading',style:Theme.of(context).textTheme.titleLarge)),Wrap(spacing:0,children:[TextButton.icon(onPressed:_chooseDate,icon:const Icon(Icons.calendar_month_outlined),label:const Text('Date')),TextButton.icon(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const PeriodReadingsScreen())),icon:const Icon(Icons.view_week_outlined),label:const Text('Weekly / monthly'))])]),Wrap(spacing:7,children:enabledCategories.map((v)=>ChoiceChip(label:Text(v[0].toUpperCase()+v.substring(1)),selected:category==v,onSelected:(_)=>setState(()=>category=v)).toList()),const SizedBox(height:12),if(loading)const Center(child:CircularProgressIndicator())else if(reading==null)const InfoCard('This category or date has no published reading in the content currently available. No old or invented reading is shown as current.')else _readingCard(reading!,s),const SizedBox(height:18),Text('More ways to reflect',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:8),Card(child:ListTile(leading:const Icon(Icons.edit_note,color:AppTheme.primary),title:const Text('Private journal'),subtitle:Text(reading?.prompt??'Write a thought for yourself.'),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>JournalScreen(prompt:reading?.prompt??'What would you like to reflect on today?'))))),const SizedBox(height:16),FutureBuilder<String?>(future:AstroRepository.instance.setting('weekly_recap'),builder:(context,enabled){if(enabled.data!='true')return const SizedBox.shrink();return FutureBuilder<Map<String,int>>(future:AstroRepository.instance.weeklyRecap(),builder:(context,recap){if(!recap.hasData)return const SizedBox.shrink();final v=recap.data!;return Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Your week, at a glance',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:8),Text(v['readings'].toString()+' readings · '+v['journal'].toString()+' journal entries · '+v['activeDays'].toString()+' active days',style:const TextStyle(color:AppTheme.muted)),const SizedBox(height:4),const Text('A simple activity summary, not an interpretation of mood or wellbeing.',style:TextStyle(color:AppTheme.muted,fontSize:11))])));}}),const DisclaimerCard()]);}
Widget _readingCard(HoroscopeReading r,ZodiacSign s)=>FutureBuilder<bool>(future:AstroRepository.instance.isSaved(r.id),builder:(context,saved)=>Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(20),border:Border.all(color:AppTheme.line)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(s.glyph+'  '+s.name.toUpperCase(),style:const TextStyle(color:AppTheme.primary,fontWeight:FontWeight.w800,fontSize:10)),const SizedBox(height:10),Text(r.title,style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:10),Text(r.body,style:Theme.of(context).textTheme.bodyLarge),const Divider(height:25),const Text('REFLECTION PROMPT',style:TextStyle(fontSize:10,fontWeight:FontWeight.w800,color:AppTheme.muted)),Text(r.prompt,style:const TextStyle(fontWeight:FontWeight.w600)),Row(children:[TextButton.icon(onPressed:()async{await AstroRepository.instance.toggleSaved({'id':r.id,'sign':r.signId,'title':r.title,'body':r.body,'prompt':r.prompt,'content_type':'reading'});setState((){});},icon:Icon(saved.data==true?Icons.bookmark:Icons.bookmark_border),label:Text(saved.data==true?'Saved':'Save')),const Spacer(),TextButton.icon(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ShareCardScreen(reading:r,sign:s))),icon:const Icon(Icons.share_outlined),label:const Text('Share card'))])]));
Future<void> _chooseSign()async{final id=await showModalBottomSheet<String>(context:context,showDragHandle:true,builder:(_)=>ListView(shrinkWrap:true,children:zodiacSigns.map((s)=>ListTile(leading:Text(s.glyph,style:const TextStyle(fontSize:25)),title:Text(s.name),onTap:()=>Navigator.pop(context,s.id))).toList()));if(id!=null){await AstroRepository.instance.setSelectedSign(id);setState(()=>sign=id);}}
Future<void> _chooseDate()async{final d=await showDatePicker(context:context,initialDate:selectedDate,firstDate:DateTime(2020),lastDate:AstroClock.editorialToday());if(d!=null){setState(()=>selectedDate=d);final r=reading;if(r!=null)await AstroRepository.instance.recordRead(r.id);}}
}
